fn replace_with_colon(str1: &Vec<char>) -> Vec<char> {
    // Preallocate the output vector with the same length as the input
    let mut output = Vec::with_capacity(str1.len());

    // For each character in the input, push either ':' (if it is
    // a space, comma, or period) or the character itself.
    for &ch in str1.iter() {
        if ch == ' ' || ch == ',' || ch == '.' {
            output.push(':');
        } else {
            output.push(ch);
        }
    }

    output
}

